```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "process_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) AS tm, round(avg(value),3) AS cpu_usage, round(max(value),3) AS cpu_max FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric='k8s.pod.cpu.usage' GROUP BY 1 ORDER BY 1",
          "claim": "Route-plan pod CPU usage jumps to about 2-4 cores in 09:03-09:06 from a normal mean of about 0.09 cores, then falls back."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) AS abn_avg FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('k8s.pod.cpu_limit_utilization','container.memory.working_set','k8s.pod.memory.working_set') GROUP BY metric",
          "claim": "Route-plan CPU limit utilisation averages about 0.15 with peaks below 0.9; memory is flat, so the container is not exhausted."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind IN ('Server','Internal','Client') GROUP BY ALL ORDER BY 2,1",
          "claim": "Route-plan server and internal spans grow to about 4 s p95, versus 1.4 s normal, while its outgoing client calls stay far shorter."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM normal_traces WHERE service_name='ts-route-plan-service' GROUP BY ALL ORDER BY 2",
          "claim": "Normal-period route-plan server p95 is about 1.4 s and internal p95 about 1.4 s (baseline for comparison)."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS tm, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms, sum(CASE WHEN attr_http_response_status_code=503 THEN 1 ELSE 0 END) AS http503 FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1 ORDER BY 1",
          "claim": "Travel-plan's POST calls to route-plan slow to several seconds and about 23 of them return 503 during the burst."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, left(span_name,60) AS sn, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' AND attr_span_kind='Server' GROUP BY ALL ORDER BY 2",
          "claim": "UI travelPlan endpoints show p95 up to about 20 s versus about 1.5-1.9 s normal, the user-visible slowdown."
        }
      ]
    }
  ]
}
```

